package com.motionstudio.part3
import com.motionstudio.part2.*
enum class SocketType{IMAGE,VIDEO,MASK,SCALAR,COLOR,ANY}
enum class NodeKind{INPUT,OUTPUT,IMAGE,VIDEO,TRANSFORM,MERGE,BLEND,BLUR,COLOR,MASK,MATTE,KEYER,NOISE,TEXT,SHAPE,PRECOMP,SWITCH}
data class Socket(val name:String,val type:SocketType)
data class NodeDef(val id:String,val type:String,val inputs:List<Socket>,val outputs:List<Socket>,val evaluate:(Map<String,Any?>)->Any?)
data class Connection(val fromNode:String,val fromSocket:String,val toNode:String,val toSocket:String)
class NodeCompositor{private val nodes=linkedMapOf<String,NodeDef>();private val conns=mutableListOf<Connection>();fun add(n:NodeDef){require(n.id !in nodes);nodes[n.id]=n};fun connect(c:Connection){val a=nodes[c.fromNode]?:error("Missing source");val b=nodes[c.toNode]?:error("Missing target");val ao=a.outputs.first{it.name==c.fromSocket};val bi=b.inputs.first{it.name==c.toSocket};require(ao.type==bi.type||ao.type==SocketType.ANY||bi.type==SocketType.ANY);conns.removeIf{it.toNode==c.toNode&&it.toSocket==c.toSocket};conns+=c;order()};fun order():List<String>{val indeg=nodes.keys.associateWith{0}.toMutableMap();conns.forEach{indeg[it.toNode]=indeg[it.toNode]!!+1};val q=ArrayDeque(indeg.filterValues{it==0}.keys);val out=mutableListOf<String>();while(q.isNotEmpty()){val n=q.removeFirst();out+=n;conns.filter{it.fromNode==n}.forEach{indeg[it.toNode]=indeg[it.toNode]!!-1;if(indeg[it.toNode]==0)q.add(it.toNode)}};require(out.size==nodes.size){"Node graph cycle"};return out};fun evaluate():Map<String,Any?>{val values=mutableMapOf<String,Any?>();for(id in order()){val input=conns.filter{it.toNode==id}.associate{it.toSocket to values[it.fromNode+":"+it.fromSocket]};val v=nodes[id]!!.evaluate(input);values[id+":out"]=v};return values}}
